options.helpers:
context.markdown.disable('code');
// an exception chip lights only when its count is above zero
context.handlebars.registerHelper('hot', (v) => (Number(v) > 0 ? 'hot' : ''));
// a station holds panels when either side has a setpoint or draws current
context.handlebars.registerHelper('occ', (a, b, p) => (a !== 's-off' || b !== 's-off' || (p !== undefined && p !== '') ? 'on' : ''));
context.handlebars.registerHelper('plural', (n, one, many) => (Number(n) === 1 ? one : many));

options.styles:
@import url('https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700&family=JetBrains+Mono:wght@500;600;700&display=swap');

/* High-performance HMI rule (ISA-101): a value that is where it should be is plain
   grey text; colour appears only where something is off. Every state colour below
   is a GRAFANA_DESIGN_SYSTEM.md section 2.1 token. */
.vcp {
  --ok: #22c55e; --warn: #f59e0b; --crit: #ef4444; --info: #00f2fe; --accent: #3b82f6; --nodata: #64748b;
  --warn-ink: #fbbf24; --crit-ink: #fca5a5; --info-ink: #67e8f9;
  --warn-bg: rgba(245, 158, 11, 0.16); --crit-bg: rgba(239, 68, 68, 0.16); --info-bg: rgba(0, 242, 254, 0.10);
  /* neutral ramp: ink-4 is the floor for small text (6.7:1 on bg-1) */
  --ink-1: #f8fafc; --ink-2: #e2e8f0; --ink-3: #cbd5e1; --ink-4: #94a3b8; --ink-5: #64748b;
  --bg-0: #0c0f14; --bg-1: #11141a; --bg-2: #161a21; --line: #232833; --line-2: #2d3340;
  /* type: 12px floor for labels, 13-16px for data, so a value reads from a step back */
  --fs-lbl: 12px; --fs-val: 15px; --fs-h: 18px; --fs-kpi: 28px;
  --mono: 'JetBrains Mono', ui-monospace, SFMono-Regular, Menlo, monospace;
  --sans: 'Inter', system-ui, -apple-system, 'Segoe UI', sans-serif;
  font-family: var(--sans); color: var(--ink-3); font-size: var(--fs-val); line-height: 1.35;
  background: var(--bg-0); padding: 10px 12px 12px; box-sizing: border-box; min-height: 100%;
}
.vcp *, .vcp *::before, .vcp *::after { box-sizing: border-box; }
.vcp b { font-weight: 600; color: var(--ink-1); }

/* toolbar */
.vcp-bar { display: flex; flex-wrap: wrap; align-items: center; gap: 8px 20px; margin-bottom: 10px; }
.vcp-pills { display: flex; gap: 6px; }
.vcp-fpill { display: inline-flex; align-items: center; gap: 6px; height: 26px; padding: 0 12px; border-radius: 13px; border: 1px solid var(--line-2); color: var(--ink-3); font-size: 12px; font-weight: 500; text-decoration: none; cursor: pointer; }
.vcp-fpill:hover { border-color: var(--ink-5); color: var(--ink-1); }
.vcp-fpill:focus-visible { outline: 2px solid var(--accent); outline-offset: 2px; }
.vcp-fpill.is-active { border-color: var(--accent); background: rgba(59, 130, 246, 0.14); color: var(--ink-1); }
.vcp-fpill b { font-family: var(--mono); }
.dot { width: 7px; height: 7px; border-radius: 50%; display: inline-block; }
.d-run { background: var(--ok); } .d-idle { background: var(--info); } .d-down { background: var(--crit); }
.vcp-fresh { font-size: 12px; color: var(--ink-4); }
.vcp-fresh .sep { margin: 0 6px; color: var(--ink-5); }
.vcp-legend { margin-left: auto; display: flex; flex-wrap: wrap; gap: 4px 14px; font-size: var(--fs-lbl); color: var(--ink-4); }
.vcp-legend span { display: inline-flex; align-items: center; gap: 5px; }
.lg { width: 12px; height: 10px; border-radius: 2px; display: inline-block; }
.lg-dev, .lg-warn { background: var(--warn-bg); box-shadow: inset 0 0 0 1px var(--warn); }
.lg-miss { box-shadow: inset 0 0 0 1px var(--crit); background: var(--crit-bg); }
.lg-nosp { box-shadow: inset 0 -2px 0 var(--info); }
.lg-note { color: var(--ink-5); }

/* fleet totals: one flat strip, no tiles */
.vcp-kpis { display: grid; grid-template-columns: repeat(5, minmax(0, 1fr)); border-top: 1px solid var(--line); border-bottom: 1px solid var(--line); margin-bottom: 12px; }
.kpi { display: flex; flex-direction: column; gap: 2px; padding: 8px 14px; border-left: 1px solid var(--line); }
.kpi:first-child { border-left: 0; padding-left: 2px; }
.k-lbl { font-size: var(--fs-lbl); color: var(--ink-4); }
.k-val { font-family: var(--mono); font-size: var(--fs-kpi); font-weight: 600; color: var(--ink-1); font-variant-numeric: tabular-nums; }
.k-val small { font-size: 13px; font-weight: 500; color: var(--ink-4); margin-left: 5px; }

/* line cards */
/* three lines side by side; a card never drops below 420 px, so narrow screens stack them */
.vcp-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(max(420px, calc((100% - 24px) / 3)), 1fr)); gap: 12px; }
.card { container-type: inline-size; background: var(--bg-1); border: 1px solid var(--line); border-top: 3px solid var(--nodata); border-radius: 6px; padding: 12px 14px; min-width: 0; }
.card.st-run { border-top-color: var(--ok); }
.card.st-idle { border-top-color: var(--info); }
.card.st-down, .card.st-alarm, .card.st-stop { border-top-color: var(--crit); }
.card.st-pm { border-top-color: var(--accent); }
/* a line silent for more than 5 minutes: the values are the last known ones */
.card.is-stale { border-top-color: var(--nodata); }
.card.is-stale .c-sec, .card.is-stale .c-job { opacity: 0.55; }
.card.is-stale .pill { filter: grayscale(1); }

.c-head { display: flex; align-items: center; justify-content: space-between; gap: 8px; }
.c-id { display: flex; align-items: center; gap: 8px; min-width: 0; }
.c-id h3 { margin: 0; font-size: var(--fs-h); font-weight: 700; color: var(--ink-1); letter-spacing: -0.01em; white-space: nowrap; }
.pill { display: inline-flex; align-items: center; gap: 5px; height: 22px; padding: 0 9px; border-radius: 11px; font-size: 12px; font-weight: 700; letter-spacing: 0.04em; color: var(--ink-2); background: rgba(100, 116, 139, 0.22); }
.pill i { width: 6px; height: 6px; border-radius: 50%; background: var(--nodata); }
.st-run .pill { color: #86efac; background: rgba(34, 197, 94, 0.14); } .st-run .pill i { background: var(--ok); }
.st-idle .pill { color: var(--info-ink); background: var(--info-bg); } .st-idle .pill i { background: var(--info); }
.st-down .pill, .st-alarm .pill, .st-stop .pill { color: var(--crit-ink); background: var(--crit-bg); }
.st-down .pill i, .st-alarm .pill i, .st-stop .pill i { background: var(--crit); }
.st-pm .pill { color: #93c5fd; background: rgba(59, 130, 246, 0.16); } .st-pm .pill i { background: var(--accent); }
.tag-test { font-size: 11px; font-weight: 600; color: var(--warn-ink); border: 1px solid rgba(245, 158, 11, 0.5); border-radius: 3px; padding: 0 5px; line-height: 18px; }
.tag-test.wf-std { display: none; }
.c-age { font-size: 13px; color: var(--ink-4); white-space: nowrap; font-variant-numeric: tabular-nums; }
.c-age.is-late { color: var(--warn-ink); font-weight: 600; }
.c-meta { display: flex; flex-wrap: wrap; gap: 2px 14px; margin: 4px 0 10px; font-size: 13px; color: var(--ink-3); font-variant-numeric: tabular-nums; }

/* current job: label / value pairs in two columns */
.c-job { display: grid; grid-template-columns: 1fr 1fr; gap: 5px 20px; margin: 0 0 4px; padding: 8px 0 10px; border-top: 1px solid var(--line); }
.c-job div { display: flex; justify-content: space-between; align-items: baseline; gap: 8px; min-width: 0; }
/* when space runs out the label gives way, never the value */
.c-job dt { font-size: var(--fs-lbl); color: var(--ink-4); white-space: nowrap; min-width: 0; overflow: hidden; text-overflow: ellipsis; }
.c-job dd { margin: 0; flex-shrink: 0; max-width: 72%; font-size: 13px; color: var(--ink-4); text-align: right; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; font-variant-numeric: tabular-nums; }
.c-job dd b, .c-job dd.mono { font-family: var(--mono); font-size: var(--fs-val); font-weight: 600; color: var(--ink-1); }

/* sections */
.c-sec { padding: 8px 0 8px; border-top: 1px solid var(--line); }
.s-head { display: flex; justify-content: space-between; align-items: baseline; gap: 10px; margin-bottom: 6px; }
.s-head > span:first-child { font-size: var(--fs-lbl); font-weight: 700; letter-spacing: 0.05em; text-transform: uppercase; color: var(--ink-3); white-space: nowrap; }
.s-note { font-size: var(--fs-lbl); color: var(--ink-4); text-align: right; font-variant-numeric: tabular-nums; }
.s-note b { font-family: var(--mono); }
.r-lbl { font-size: var(--fs-lbl); color: var(--ink-4); text-align: left !important; white-space: nowrap; font-family: var(--sans) !important; font-weight: 400 !important; }

/* baths: 10 columns, the 3 support baths after a gap */
.baths { display: grid; gap: 1px 0; }
.b-row { display: grid; grid-template-columns: 62px repeat(7, minmax(0, 1fr)) 10px repeat(3, minmax(0, 1fr)); align-items: center; }
.b-row > span { text-align: center; font-variant-numeric: tabular-nums; padding: 2px 0; border-radius: 3px; }
.b-row > .b-gap { grid-column-start: 10; }
.b-name { align-items: end; }
.b-name > span { font-size: var(--fs-lbl); color: var(--ink-4); line-height: 1.15; }
.b-read > span { font-family: var(--mono); font-size: 16px; font-weight: 700; color: var(--ink-1); }
.b-set > span { font-family: var(--mono); font-size: 13px; color: var(--ink-4); }
.b-read .st-warn { color: var(--warn-ink); background: var(--warn-bg); box-shadow: inset 0 0 0 1px rgba(245, 158, 11, 0.55); }
.b-read .st-na { color: var(--ink-5); font-weight: 400; }

/* stations: bank a above the conveyor rail, bank b below, 18 aligned columns */
.topo, .pumps { display: grid; gap: 1px 0; }
.t-row { display: grid; grid-template-columns: 44px repeat(18, minmax(0, 1fr)); column-gap: 1px; align-items: center; }
.t-row > span { text-align: center; font-family: var(--mono); font-variant-numeric: tabular-nums; white-space: nowrap; overflow: hidden; line-height: 21px; }
/* the two current rows carry a faint band so they read apart from the voltage rows */
.t-amp { background: var(--bg-2); border-radius: 3px; }
.t-amp > span { font-size: 13px; font-weight: 700; color: var(--ink-1); border-radius: 3px; }
.t-volt > span { font-size: 11px; letter-spacing: -0.04em; color: var(--ink-3); }
.rail { background: transparent; border-top: 1px dashed var(--line-2); border-bottom: 1px dashed var(--line-2); border-radius: 3px; margin: 2px 0; padding: 1px 0; }
.t-idx > span { font-size: 12px; font-weight: 600; color: var(--ink-4); }
.t-set > span { font-size: 13px; color: var(--ink-3); }
/* side states: plain = within 5 A of setpoint; colour only for the off cases */
.c.s-off::before { content: '–'; color: var(--line-2); font-weight: 400; }
.c.s-dev { color: var(--warn-ink); background: var(--warn-bg); box-shadow: inset 0 0 0 1px rgba(245, 158, 11, 0.6); }
.c.s-miss { color: var(--crit-ink); background: var(--crit-bg); box-shadow: inset 0 0 0 1px var(--crit); }
.c.s-nosp { color: var(--info-ink); box-shadow: inset 0 -2px 0 var(--info); }
.bank-sum { display: flex; flex-wrap: wrap; gap: 2px 22px; margin-top: 8px; font-size: 13px; color: var(--ink-3); font-variant-numeric: tabular-nums; }
.bank-sum b { font-family: var(--mono); margin-right: 3px; }
.s-note .n-dev, .s-note .n-miss, .s-note .n-open, .s-note .n-crit { color: var(--ink-1); }

/* pumps */
.t-pmp { background: var(--bg-2); border-radius: 3px; }
.t-pmp > .p { font-size: 13px; font-weight: 700; color: var(--ink-1); border-radius: 3px; }
.p.is-dev { color: var(--warn-ink); background: var(--warn-bg); box-shadow: inset 0 0 0 1px rgba(245, 158, 11, 0.6); }
.p.is-off { color: var(--ink-5); font-weight: 400; }

/* alarms */
.al { list-style: none; margin: 0; padding: 0; display: grid; gap: 2px; }
.al li { display: grid; grid-template-columns: 68px 44px minmax(0, 1fr) auto; gap: 8px; align-items: baseline; padding: 3px 6px; border-left: 3px solid transparent; font-size: 13px; }
.al li.is-open { border-left-color: var(--crit); background: rgba(239, 68, 68, 0.06); }
/* fewer than four triggers in range: drop the empty slots, keep the "no alarm" line */
.al li:has(.msg:empty) { display: none; }
.al li:not(.is-open):not(.is-clear) time, .al code:empty { visibility: hidden; }
.al time { font-family: var(--mono); color: var(--ink-3); font-variant-numeric: tabular-nums; }
.al code { font-family: var(--mono); font-weight: 700; color: var(--ink-3); background: none; padding: 0; }
.al code.al-crit { color: var(--crit-ink); }
.al code.al-warn { color: var(--warn-ink); }
.al .msg { color: var(--ink-1); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.al .dur { color: var(--ink-3); white-space: nowrap; font-variant-numeric: tabular-nums; text-align: right; }
.al li.is-open .dur { color: var(--crit-ink); font-weight: 600; }
.al li:not(.is-open):not(.is-clear) .msg { color: var(--ink-4); }
.al-top { margin-top: 6px; font-size: 13px; color: var(--ink-3); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.al-top span { font-size: var(--fs-lbl); color: var(--ink-4); margin-right: 6px; }

.vcp-empty { grid-column: 1 / -1; display: flex; flex-direction: column; gap: 4px; align-items: center; padding: 48px 16px; border: 1px dashed var(--line-2); border-radius: 6px; color: var(--ink-4); }

/* a narrow card (screens of about 1,400 px and down) hides the two voltage rows;
   every cell's tooltip still carries its voltage, and the bank summary its mean */
@container (max-width: 500px) {
  .t-volt { display: none; }
  .card { padding-left: 8px; padding-right: 8px; }
  .t-row { grid-template-columns: 34px repeat(18, minmax(0, 1fr)); column-gap: 1px; }
  .t-amp > span, .t-pmp > .p, .t-set > span, .t-idx > span { font-size: 10.5px; letter-spacing: -0.04em; }
  .b-row { grid-template-columns: 52px repeat(7, minmax(0, 1fr)) 6px repeat(3, minmax(0, 1fr)); }
  .b-read > span { font-size: 12.5px; letter-spacing: -0.03em; }
  .b-set > span { font-size: 12px; }
  .c-job dd b, .c-job dd.mono { font-size: 14px; }
  .al li { grid-template-columns: 64px 40px minmax(0, 1fr) auto; font-size: 12px; }
  .c-job { gap: 3px 12px; }
}
@media (prefers-reduced-motion: reduce) { .vcp * { transition: none !important; animation: none !important; } }

/* v8 · hero row: the four numbers a supervisor reads first, one step larger than anything else on the card */
.hero { display: grid; grid-template-columns: 1fr 1fr 1fr 1.25fr; gap: 0; margin: 0 0 10px; border-top: 1px solid var(--line); border-bottom: 1px solid var(--line); }
.hero > div { padding: 8px 10px; border-left: 1px solid var(--line); min-width: 0; }
.hero > div:first-child { border-left: 0; padding-left: 0; }
.hero dt { font-size: var(--fs-lbl); color: var(--ink-4); margin-bottom: 2px; }
.hero dd { margin: 0; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; font-variant-numeric: tabular-nums; }
.hero dd b { font-family: var(--mono); font-size: 24px; font-weight: 700; color: var(--ink-1); letter-spacing: -0.02em; }
.hero dd b.job { font-size: 18px; }
.hero dd small { font-size: 13px; color: var(--ink-4); margin-left: 4px; }
.hero dd.sub { font-size: 12px; color: var(--ink-3); margin-top: 1px; }

/* v8 · exception chips: grey outline at 0, filled colour above 0, so the eye lands on what is wrong */
.chips { display: flex; flex-wrap: wrap; gap: 6px; margin: 0 0 10px; }
.chip { display: inline-flex; align-items: baseline; gap: 5px; padding: 3px 10px; border-radius: 4px; border: 1px solid var(--line-2); font-size: 12px; color: var(--ink-4); }
.chip b { font-family: var(--mono); font-size: 14px; color: var(--ink-3); margin-left: 2px; }
.chip.warn.hot { border-color: var(--warn); background: var(--warn-bg); color: var(--warn-ink); }
.chip.crit.hot { border-color: var(--crit); background: var(--crit-bg); color: var(--crit-ink); }
.chip.hot b { color: inherit; font-size: 15px; }
.card.is-stale .chips, .card.is-stale .hero { opacity: 0.55; }

/* v8 · folded detail: one click away, never in the way */
.more { margin-top: 6px; }
.more > summary { cursor: pointer; list-style: none; font-size: var(--fs-lbl); color: var(--ink-4); padding: 4px 0; user-select: none; }
.more > summary::-webkit-details-marker { display: none; }
.more > summary::before { content: '▸'; display: inline-block; width: 14px; color: var(--ink-5); }
.more[open] > summary::before { content: '▾'; }
.more > summary:hover { color: var(--ink-2); }
.more > summary:focus-visible { outline: 2px solid var(--accent); outline-offset: 2px; }
.more .c-job { border-top: 0; padding-top: 4px; }
.card > .more { border-top: 1px solid var(--line); padding-top: 4px; }

@container (max-width: 500px) {
  .hero dd b { font-size: 19px; }
  .hero dd b.job { font-size: 15px; }
  .hero > div { padding: 6px 6px; }
  .hero dd.sub { font-size: 11px; }
  .chip { font-size: 11px; padding: 2px 7px; }
  .hero { grid-template-columns: 1fr 1fr; }
  .hero > div:nth-child(3) { border-left: 0; padding-left: 0; }
  .hero > div:nth-child(n+3) { border-top: 1px solid var(--line); }
  .s-head .s-note.hint { display: none; }
}

/* ===== v9 · one screen, no scroll ===== */
.vcp { padding: 8px 12px 10px; }
.vcp-bar { margin-bottom: 6px; }
.vcp-kpis { margin-bottom: 10px; }
.kpi { flex-direction: row; align-items: baseline; gap: 10px; padding: 6px 14px; }
.k-val { font-size: 22px; }
.card { padding: 10px 12px 8px; }
.c-meta { margin: 2px 0 8px; }
.hero { margin: 0 0 8px; }
.hero > div { padding: 5px 10px; }
.hero dd b { font-size: 22px; }
.hero dd b.job { font-size: 17px; }
.chips { margin: 0 0 4px; gap: 5px; }
.chip { padding: 2px 9px; }
.c-sec { padding: 6px 0; }
.s-head { margin-bottom: 4px; }
.t-row > span { line-height: 20px; }

/* a running side or pump is a raised neutral tile; an idle one is a faint dash. Colour stays for faults. */
.t-amp { background: transparent; }
.t-amp > span, .t-pmp > .p { margin: 1px 0; }
.c.s-on, .p.is-on { background: #1f2631; box-shadow: inset 0 -2px 0 #3b4658; color: var(--ink-1); }
.p.is-off::before { content: ''; }
.t-pmp { background: transparent; }
.pump-block { margin-top: 5px; padding-top: 3px; border-top: 1px dashed var(--line-2); }
.t-pidx > span { font-size: 11px; color: var(--ink-5); font-weight: 500; }

.b-read > span { font-size: 15px; }
.b-name > span { line-height: 1.05; }
.al { gap: 1px; }
.al li { padding: 2px 6px; font-size: 12.5px; }
.al-top { margin-top: 4px; font-size: 12px; }

/* the two folds sit on one line until one is opened */
.folds { display: flex; flex-wrap: wrap; column-gap: 22px; border-top: 1px solid var(--line); padding-top: 2px; }
.folds .more { margin-top: 0; }
.folds .more[open] { flex-basis: 100%; }
.card > .more { border-top: 0; }

@container (max-width: 500px) {
  .hero dd b { font-size: 18px; }
  .kpi { padding: 5px 8px; }
}

/* v9b · header carries since + data age; hero stays one row even on narrow cards */
.c-head { margin-bottom: 8px; align-items: baseline; }
.c-head .c-meta { margin: 0; gap: 2px 12px; justify-content: flex-end; font-size: 12px; }
.c-head .c-meta .c-age { font-size: 12px; }
.b-name > span { white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.pump-block { margin-top: 4px; padding-top: 2px; }
.topo { margin-bottom: 2px; }
@container (max-width: 500px) {
  .hero { grid-template-columns: 1fr 1fr 1fr 1.3fr; }
  .hero > div:nth-child(3) { border-left: 1px solid var(--line); padding-left: 6px; }
  .hero > div:nth-child(n+3) { border-top: 0; }
  .hero dd b { font-size: 17px; }
  .hero dd b.job { font-size: 13px; }
  .hero dd small { font-size: 11px; margin-left: 2px; }
  .hero dd.sub { font-size: 10.5px; }
  .hero dt { font-size: 11px; }
  .c-head .c-meta { font-size: 11px; }
  .chip { font-size: 11px; padding: 1px 6px; }
}

/* v9c · names never wrap; narrow cards get tighter bath digits */
.b-name > span { font-size: 11px; letter-spacing: -0.02em; }
.tag-test { white-space: nowrap; }
@container (max-width: 500px) {
  .b-row { grid-template-columns: 44px repeat(7, minmax(0, 1fr)) 4px repeat(3, minmax(0, 1fr)); }
  .b-read > span { font-size: 12px; letter-spacing: -0.04em; }
  .b-set > span { font-size: 10.5px; letter-spacing: -0.04em; }
  .b-name > span { font-size: 9.5px; }
  .b-row .r-lbl { font-size: 10.5px; }
}

/* ===== v10 · display only, everything visible ===== */
.vcp-counts { display: flex; flex-wrap: wrap; align-items: center; gap: 4px 14px; font-size: 12px; color: var(--ink-4); }
.vcp-counts span { display: inline-flex; align-items: center; gap: 5px; }
.vcp-counts b { font-family: var(--mono); color: var(--ink-1); font-size: 13px; }
.vcp-counts .sep { padding-left: 14px; border-left: 1px solid var(--line-2); }

/* where the panels are: a track of 18 stations between the untracked tanks before and after */
.where { margin: 2px 0 6px; padding: 6px 8px; border-radius: 4px; background: rgba(0, 242, 254, 0.05); border: 1px solid rgba(0, 242, 254, 0.18); }
.w-text { font-size: 12px; color: var(--ink-3); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.w-lbl { color: var(--ink-4); }
.w-text b { font-family: var(--mono); font-size: 15px; color: var(--info-ink); margin: 0 6px 0 2px; }
.w-sub { color: var(--ink-3); }
.w-track { display: flex; align-items: center; gap: 6px; margin-top: 5px; }
.zone { flex: 0 0 auto; font-size: 10.5px; color: var(--ink-5); padding: 1px 6px; border: 1px dashed var(--line-2); border-radius: 3px; white-space: nowrap; }
.arrow { color: var(--ink-5); font-size: 11px; }
.segs { flex: 1 1 auto; display: grid; grid-template-columns: repeat(18, minmax(0, 1fr)); gap: 2px; }
.seg { display: block; height: 10px; border-radius: 2px; background: var(--line); }
.seg.on { background: var(--info); box-shadow: 0 0 6px rgba(0, 242, 254, 0.35); }
.card.is-stale .where { opacity: 0.55; }

/* voltages back on screen, one step quieter than the currents */
.t-volt > span { line-height: 16px; }
.t-pset > span { font-size: 11.5px; color: var(--ink-4); line-height: 17px; }

/* job record as one wrapped line */
.spec { display: flex; flex-wrap: wrap; gap: 2px 14px; padding-top: 6px; border-top: 1px solid var(--line); font-size: 11.5px; color: var(--ink-4); }
.spec b { font-family: var(--mono); color: var(--ink-2); font-weight: 600; }

@container (max-width: 500px) {
  .zone { font-size: 9.5px; padding: 1px 4px; }
  .w-text b { font-size: 13px; }
  .t-volt { display: grid; }
  .t-volt > span { font-size: 9px; letter-spacing: -0.08em; }
  .w-text { white-space: normal; }
  .t-pset > span { font-size: 10px; letter-spacing: -0.04em; }
  .spec { font-size: 10.5px; gap: 1px 10px; }
}

/* ===== v11 · 18 plating rectifiers are the main block ===== */
.rect .s-head > span:first-child { color: var(--ink-1); font-size: 13px; letter-spacing: 0.04em; }
.t-rect { margin: 2px 0; }
.t-rect > .c { display: flex; flex-direction: column; align-items: center; justify-content: center; min-height: 36px; padding: 2px 0; border-radius: 4px; font-family: var(--mono); color: var(--ink-1); line-height: 1.1; }
.t-rect > .c b { font-size: 14px; font-weight: 700; color: inherit; letter-spacing: -0.02em; }
.t-rect > .c i { font-style: normal; font-size: 10px; font-weight: 500; color: var(--ink-4); letter-spacing: -0.03em; }
.t-rect > .c.s-dev i, .t-rect > .c.s-miss i { color: inherit; opacity: 0.85; }
.t-rect > .c.s-off::before { content: '–'; color: var(--line-2); }
.t-rect > .c.s-off b, .t-rect > .c.s-off i { display: none; }
.t-rect .r-lbl { font-size: 12px; color: var(--ink-3) !important; font-weight: 600 !important; }

/* pumps: the setpoint appears only when the reading is off it */
.t-pmp > .p { display: flex; flex-direction: column; align-items: center; line-height: 1.1; padding: 2px 0; }
.t-pmp > .p b { font-weight: 700; color: inherit; }
.t-pmp > .p i { display: none; font-style: normal; font-size: 9.5px; font-weight: 600; }
.t-pmp > .p.is-dev i { display: block; }

@container (max-width: 500px) {
  .t-rect > .c { min-height: 30px; }
  .t-rect > .c b { font-size: 11px; }
  .t-rect > .c i { font-size: 8.5px; letter-spacing: -0.08em; }
  .t-rect .r-lbl { font-size: 10.5px; }
  .t-pmp > .p i { font-size: 8.5px; }
}

/* ===== v12 · SCADA overview: line cards, full-width rectifier matrix, detail cards ===== */
.v12 .vcp-grid { margin-bottom: 10px; }
.v12 .card { padding: 8px 12px 8px; }
.v12 .hero { margin-bottom: 6px; }
.v12 .hero dd b { font-size: 21px; }
.v12 .where { margin-bottom: 0; }
.v12 .c-head.small h3 { font-size: 14px; }
.v12 .card.low .c-sec:first-of-type { border-top: 0; padding-top: 2px; }

.mx { margin: 0 0 10px; padding: 8px 12px 10px; background: var(--bg-1); border: 1px solid var(--line); border-radius: 6px; }
.mx-title { display: flex; justify-content: space-between; align-items: baseline; gap: 12px; margin-bottom: 6px; }
.mx-title > span:first-child { font-size: 14px; font-weight: 700; letter-spacing: 0.04em; text-transform: uppercase; color: var(--ink-1); }
.mx-note { font-size: 11.5px; color: var(--ink-4); }
.mx-line { display: grid; grid-template-columns: 150px 1fr; column-gap: 8px; padding: 5px 0; border-top: 1px solid var(--line); }
.mx-line > .mx-name { grid-row: span 3; display: flex; flex-direction: column; justify-content: center; gap: 4px; border-left: 3px solid var(--nodata); padding-left: 8px; }
.mx-line.st-run > .mx-name { border-left-color: var(--ok); }
.mx-line.st-idle > .mx-name { border-left-color: var(--info); }
.mx-line.st-down > .mx-name, .mx-line.st-alarm > .mx-name, .mx-line.st-stop > .mx-name { border-left-color: var(--crit); }
.mx-line.st-pm > .mx-name { border-left-color: var(--accent); }
.mx-line.is-stale > .mx-name { border-left-color: var(--nodata); }
.mx-line.is-stale .mx-row { opacity: 0.55; }
.mx-name b { font-size: 15px; color: var(--ink-1); }
.mx-name .pill { align-self: flex-start; }
.mx-sub { font-size: 11px; color: var(--ink-4); font-variant-numeric: tabular-nums; }
.mx-row { grid-column: 2; display: grid; grid-template-columns: 52px repeat(18, minmax(0, 1fr)); column-gap: 3px; align-items: center; }
.mx-head { display: grid; grid-template-columns: 150px 52px repeat(18, minmax(0, 1fr)); column-gap: 3px; margin-bottom: 2px; }
.mx-head > .mx-name { grid-column: 1; }
.mx-head > span { font-family: var(--mono); font-size: 12px; font-weight: 700; color: var(--ink-3); text-align: center; }
.mx-head { column-gap: 3px; }
.mx-head > .mx-lbl { text-align: left; }
.mx-head { grid-template-columns: 158px 52px repeat(18, minmax(0, 1fr)); }
.mx-lbl { font-size: 11.5px; font-weight: 600; color: var(--ink-3); white-space: nowrap; }
.mx-row > .c { display: flex; align-items: baseline; justify-content: center; gap: 5px; height: 26px; align-items: center; border-radius: 4px; font-family: var(--mono); font-variant-numeric: tabular-nums; color: var(--ink-1); white-space: nowrap; overflow: hidden; }
.mx-row > .c b { font-size: 15px; font-weight: 700; color: inherit; }
.mx-row > .c i { font-style: normal; font-size: 11px; color: var(--ink-4); }
.mx-row > .c.s-off::before { content: '–'; color: var(--line-2); }
.mx-row > .c.s-off b, .mx-row > .c.s-off i { display: none; }
.mx-row > .c.s-dev i, .mx-row > .c.s-miss i { color: inherit; }
.mx-set > span { text-align: center; font-family: var(--mono); font-size: 11.5px; color: var(--ink-4); line-height: 16px; }
.mx-set { border-top: 1px dashed var(--line-2); border-bottom: 1px dashed var(--line-2); margin: 2px 0; }


/* v12b · header shares the line grid; position text lives in the name cell */
.mx-headline { border-top: 0; padding: 0 0 2px; }
.mx-headline > .mx-name { grid-row: auto; border-left: 0; }
.mx-head > span { font-family: var(--mono); font-size: 12px; font-weight: 700; color: var(--ink-3); text-align: center; }
.mx-head > .mx-lbl { text-align: left; font-family: var(--sans); }
.mx-where { font-size: 11px; color: var(--ink-4); line-height: 1.35; }
.mx-where b { font-family: var(--mono); font-size: 12.5px; color: var(--info-ink); }
.mx-line { grid-template-columns: 170px 1fr; }

/* v12c · header columns match the line rows exactly */
.mx-headline .mx-head { grid-template-columns: 52px repeat(18, minmax(0, 1fr)); column-gap: 3px; margin: 0; }
.t-pmp > .p i { color: var(--warn-ink); }

/* v12d · stale lines grey their matrix pill; narrow cards keep the four chips on one row */
.mx-line.is-stale .pill { filter: grayscale(1); }
@container (max-width: 500px) {
  .chips { gap: 3px; flex-wrap: nowrap; }
  .chip { font-size: 10px; padding: 1px 5px; gap: 3px; white-space: nowrap; }
  .chip b { font-size: 12px; }
  .chip.hot b { font-size: 12px; }
  .spec { font-size: 10px; gap: 0 8px; }
}
